import * as React from 'react';

function getStrictContext<T>(
  name?: string,
): readonly [
  ({
    value,
    children,
  }: {
    value: T;
    children?: React.ReactNode;
  }) => React.JSX.Element,
  () => T,
] {
  const Context = React.createContext<T | undefined>(undefined);

  const Provider = ({
    value,
    children,
  }: {
    value: T;
    children?: React.ReactNode;
  }) => <Context.Provider value={value}>{children}</Context.Provider>;

  const useSafeContext = () => {
    const ctx = React.useContext(Context);
    if (ctx === undefined) {
      throw new Error(`useContext must be used within ${name ?? 'a Provider'}`);
    }
    return ctx;
  };

  return [Provider, useSafeContext] as const;
}

export { getStrictContext };

'use client';

import * as React from 'react';
import {
  OverlayTriggerStateContext,
  Popover as PopoverPrimitive,
  PopoverContext,
  useSlottedContext,
  type PopoverProps as PopoverPrimitiveProps,
} from 'react-aria-components';
import { AnimatePresence, motion, useIsPresent } from 'motion/react';

import {
  ReducedMotionConfig,
  useShouldReduceMotion,
  type CheckAnimation,
} from '../../../utils/motion';
import {
  asMotion,
  mergeRefs,
  useAnchoredMotion,
  type AnchoredAnimationProps,
} from '../../../internal/anchored';
import { useStaggerOnOpen } from '../../../internal/stagger';
import {
  CheckRegistryContext,
  usePickHold,
  PickContext,
  usePicks,
  type Picked,
} from '../../../internal/item-indicator';
import { originFor } from './origin';

type PopoverProps = PopoverPrimitiveProps & AnchoredAnimationProps;

const MENU_TRIGGERS = new Set([
  'MenuTrigger',
  'SubmenuTrigger',
  'Select',
  'ComboBox',
]);

type PopoverContextValue = PopoverPrimitiveProps | null | undefined;

const FOCUS_TARGET = '[role=menu],[role=listbox],[role=dialog]';

type LivePopoverProps = PopoverPrimitiveProps &
  React.RefAttributes<HTMLElement>;

const LivePropsContext = React.createContext<LivePopoverProps | null>(null);

type ListTriggerState = {
  selectionManager?: {
    selectionMode: string;
    selectedKeys: 'all' | Iterable<string | number>;
  };
};

function selectionOf(state: ListTriggerState | null) {
  const keys = state?.selectionManager?.selectedKeys;
  if (keys === undefined || keys === 'all') return keys;
  return [...keys].join('\u0000');
}

function Popover({
  transition,
  exitTransition,
  ref,
  ...props
}: PopoverProps & React.RefAttributes<HTMLElement>) {
  const context = useSlottedContext(
    PopoverContext,
    props.slot,
  ) as PopoverContextValue;
  const triggerState = React.use(OverlayTriggerStateContext);

  const isOpenProp = props.isOpen ?? context?.isOpen;
  const defaultOpen = props.defaultOpen ?? context?.defaultOpen;
  const local = isOpenProp != null || defaultOpen != null || !triggerState;
  const [uncontrolled, setUncontrolled] = React.useState(defaultOpen ?? false);
  const open = local
    ? (isOpenProp ?? uncontrolled)
    : (triggerState?.isOpen ?? false);

  const onOpenChange = (next: boolean) => {
    if (isOpenProp == null) setUncontrolled(next);
    props.onOpenChange?.(next);
  };

  const list = triggerState as ListTriggerState | null;
  const selection = selectionOf(list);
  const [openedWith, setOpenedWith] = React.useState(selection);
  const [wasOpen, setWasOpen] = React.useState(open);
  const openChanged = wasOpen !== open;
  if (openChanged) {
    setWasOpen(open);
    if (open) setOpenedWith(selection);
  }
  const picked =
    !open &&
    list?.selectionManager?.selectionMode === 'single' &&
    selection !== openedWith;
  const reduce = useShouldReduceMotion();
  const parentPicks = React.use(PickContext);
  const { picks, registerCheck, wasPicked } = usePicks();
  const menuPicks = React.useMemo(
    () => ({
      markPick: (look: CheckAnimation) => {
        picks.markPick(look);
        parentPicks?.markPick(look);
      },
      hasCheck: picks.hasCheck,
      checkOf: picks.checkOf,
    }),
    [picks, parentPicks],
  );
  const [menuPicked, setMenuPicked] = React.useState<Picked>(false);
  if (openChanged) setMenuPicked(!open && wasPicked());
  const popoverProps = {
    ...props,
    ref,
    ...(local && { isOpen: open, defaultOpen: undefined, onOpenChange }),
  };

  return (
    <ReducedMotionConfig>
      <PickContext value={menuPicks}>
        <CheckRegistryContext value={registerCheck}>
          <LivePropsContext value={popoverProps}>
            <AnimatePresence
              custom={reduce ? false : menuPicked || (picked && 'list')}
            >
              {open && (
                <AnimatedPopover
                  key="popover"
                  popoverProps={popoverProps}
                  transition={transition}
                  exitTransition={exitTransition}
                  checkOf={picks.checkOf}
                />
              )}
            </AnimatePresence>
          </LivePropsContext>
        </CheckRegistryContext>
      </PickContext>
      {!open && <PopoverPrimitive {...popoverProps} />}
    </ReducedMotionConfig>
  );
}

type AnimatedPopoverProps = AnchoredAnimationProps & {
  popoverProps: LivePopoverProps;
  checkOf: () => Picked;
};

function AnimatedPopover({
  popoverProps,
  transition,
  exitTransition,
  checkOf,
}: AnimatedPopoverProps) {
  const { render, isExiting, ...props } =
    React.use(LivePropsContext) ?? popoverProps;
  const isPresent = useIsPresent();
  const context = useSlottedContext(
    PopoverContext,
    props.slot,
  ) as PopoverContextValue;
  const trigger = props.trigger ?? context?.trigger;
  const nodeRef = React.useRef<HTMLElement | null>(null);
  const wasPresentRef = React.useRef(isPresent);
  React.useEffect(() => {
    const returned = isPresent && !wasPresentRef.current;
    wasPresentRef.current = isPresent;
    const node = nodeRef.current;
    if (
      !returned ||
      !node ||
      trigger === 'ComboBox' ||
      node.contains(document.activeElement)
    )
      return;
    const target = node.matches(FOCUS_TARGET)
      ? node
      : (node.querySelector<HTMLElement>(FOCUS_TARGET) ?? node);
    target.focus({ preventScroll: true });
  }, [isPresent, trigger]);
  const skip = Boolean(
    props.shouldSkipAnimation ?? context?.shouldSkipAnimation,
  );
  useStaggerOnOpen(nodeRef, isPresent, {
    skip: skip || !(trigger && MENU_TRIGGERS.has(trigger)),
  });
  const { exit, ...motionProps } = useAnchoredMotion({
    kind: trigger && MENU_TRIGGERS.has(trigger) ? 'menu' : 'popover',
    open: true,
    instant: skip,
    transition,
    exitTransition,
  });
  const hold = usePickHold();
  const variants = {
    exit: (held: Picked | 'list' | undefined) => {
      const look = held === 'list' ? checkOf() : held;
      if (!look) return exit;
      const leave = exit.transition as { delay?: number } | undefined;
      return {
        ...exit,
        transition: { ...leave, delay: (leave?.delay ?? 0) + hold(look) },
      };
    },
  };

  return (
    <PopoverPrimitive
      {...props}
      isExiting={isExiting || !isPresent}
      render={(domProps, values) => {
        const elementProps = {
          ...motionProps,
          ref: mergeRefs(
            (domProps as { ref?: React.Ref<HTMLElement> }).ref,
            nodeRef,
          ),
          exit: 'exit',
          variants,
          style: {
            transformOrigin: originFor(values.placement),
            ...domProps.style,
            ...motionProps.style,
          },
        };
        return render ? (
          asMotion(render(domProps, values), elementProps)
        ) : (
          <motion.div
            {...(domProps as Record<string, unknown>)}
            {...elementProps}
          />
        );
      }}
    />
  );
}

export { Popover, type PopoverProps };

'use client';

import * as React from 'react';

type PreviewImageOptions = {
  src?: string;
  width?: number;
  height?: number;
  deviceScaleFactor?: number;
  colorScheme?: 'light' | 'dark';
};

function buildQueryString(
  params: Record<string, string | number | boolean | undefined | null>,
) {
  const search = new URLSearchParams();
  for (const [key, value] of Object.entries(params)) {
    if (value === undefined || value === null) continue;
    search.append(key, String(value));
  }
  return search.toString();
}

function buildPreviewSrc({
  href,
  width,
  height,
  deviceScaleFactor,
  colorScheme,
}: Required<Omit<PreviewImageOptions, 'src'>> & { href: string }) {
  return `https://api.microlink.io/?${buildQueryString({
    url: href,
    screenshot: true,
    meta: false,
    embed: 'screenshot.url',
    colorScheme,
    'viewport.isMobile': true,
    'viewport.deviceScaleFactor': deviceScaleFactor,
    'viewport.width': width * 3,
    'viewport.height': height * 3,
  })}`;
}

function usePreloadImage(src: string) {
  React.useEffect(() => {
    const link = document.createElement('link');
    link.rel = 'preload';
    link.as = 'image';
    link.href = src;
    document.head.appendChild(link);
    return () => {
      link.remove();
    };
  }, [src]);
}

export { buildPreviewSrc, usePreloadImage, type PreviewImageOptions };

'use client';

import * as React from 'react';
import {
  createGeneratorEasing,
  generateLinearEasing,
  MotionConfig,
  MotionConfigContext,
  spring as springGenerator,
  type Transition,
} from 'motion/react';

const ease = {
  out: [0.23, 1, 0.32, 1],
  soft: [0.215, 0.61, 0.355, 1],
  draw: [0, 0, 0.58, 1],
  inOut: [0.77, 0, 0.175, 1],
  away: [0.33, 0.17, 0.67, 0.5],
  in: [0.4, 0, 1, 1],
  drawer: [0.34, 1.2, 0.64, 1],
  arrive: [0.11, 0, 0.5, 0],
  color: [0.25, 0.1, 0.25, 1],
  leave: [0, 0, 0.58, 1],
  enter: [0.25, 0.1, 0.35, 1],
  resize: [0.4, 0, 0.1, 1],
  fill: [0.4, 0, 0.2, 1],
} as const;

const spring = {
  press: { type: 'spring', stiffness: 550, damping: 30, restSpeed: 10 },
  pop: { type: 'spring', stiffness: 400, damping: 29 },
  tooltip: { type: 'spring', stiffness: 400, damping: 31 },
  dialog: { type: 'spring', stiffness: 150, damping: 25 },
  toast: { type: 'spring', stiffness: 280, damping: 24 },
  selection: { type: 'spring', stiffness: 300, damping: 30 },
  highlight: { type: 'spring', stiffness: 500, damping: 40 },
  reflow: { type: 'spring', stiffness: 500, damping: 40 },
  handoff: { type: 'spring', stiffness: 450, damping: 43 },
  morph: { type: 'spring', stiffness: 660, damping: 52 },
  height: {
    type: 'spring',
    stiffness: 300,
    damping: 30,
    bounce: 0,
    restDelta: 0.01,
  },
  slide: { type: 'spring', stiffness: 300, damping: 35, restDelta: 0.01 },
  thumb: { type: 'spring', stiffness: 300, damping: 25 },
  slider: { type: 'spring', stiffness: 400, damping: 32 },
  bounce: { type: 'spring', stiffness: 200, damping: 16 },
  glyph: { type: 'spring', stiffness: 500, damping: 45 },
  checkPop: { type: 'spring', stiffness: 500, damping: 24 },
  entrance: { type: 'spring', stiffness: 200, damping: 20 },
  progress: {
    type: 'spring',
    stiffness: 300,
    damping: 35,
    restDelta: 0.01,
    restSpeed: 0.1,
  },
  number: { type: 'spring', stiffness: 90, damping: 50 },
} as const satisfies Record<string, Transition>;

const transition = {
  menu: { duration: 0.22, ease: ease.soft },
  overlay: { duration: 0.4, ease: ease.soft },
  dialogFade: { duration: 0.4, ease: ease.soft },
  fade: { duration: 0.2, ease: ease.out },
  color: { duration: 0.2, ease: ease.color },
  reveal: { duration: 0.3, ease: ease.out },
  disclosure: { duration: 0.35, ease: ease.soft },
  panelOut: { duration: 0.15, ease: ease.leave },
  panelIn: { duration: 0.3, ease: ease.enter },
  tooltipIn: { duration: 0.34, ease: ease.enter },
  tooltipOut: { duration: 0.13, ease: ease.leave },
  panelHeight: { duration: 0.45, ease: ease.resize },
  check: { duration: 0.3, delay: 0.2, ease: ease.draw },
  uncheck: { duration: 0.3, ease: ease.draw },
  fill: { duration: 0.3, ease: ease.fill },
  popOut: { duration: 0.15, ease: ease.out },
  swap: { duration: 0.15, ease: ease.out },
  spin: { duration: 0.3, ease: ease.out },
  handoffOut: { duration: 0.22, ease: ease.soft },
  handoffIn: { duration: 0.26, ease: ease.arrive },
  dismiss: { duration: 0.2, ease: ease.away },
  shake: { duration: 0.4, ease: ease.inOut },
  drawerOut: { duration: 0.16, ease: ease.in },
  drawer: { duration: 0.4, ease: ease.drawer },
  sheet: { duration: 0.4, ease: ease.soft },
  collapse: { duration: 0.28, ease: ease.inOut },
  collapseLabel: { duration: 0.14, ease: ease.out },
  instant: { duration: 0 },
} as const satisfies Record<string, Transition>;

const scale = {
  press: 0.97,
  choice: 0.985,
  tooltip: 0.7,
  popover: 0.8,
  menu: 0.9,
  dialog: 0.8,
  icon: 0.5,
  toast: 0.96,
  fill: 0.7,
  action: 0.9,
} as const;

const blur = {
  icon: 'blur(2px)',
  tooltip: 'blur(6px)',
  disclosure: 'blur(2px)',
  surface: 'blur(4px)',
  panel: 'blur(5px)',
} as const;

const rotate = {
  icon: 90,
} as const;

const shift = {
  handoff: 6,
  navigation: 24,
  tabs: 12,
  step: 24,
  tooltip: 40,
  shake: 3,
} as const;

const stagger: { readonly stack: number } = {
